":"this weekend"},{"id":"next_week","label":"next week"}],"practiceWhenLead":"I will do it {pick}.","practiceWho":[{"id":"family","label":"a family member"},{"id":"neighbor","label":"a neighbor"},{"id":"friend","label":"a friend"}],"practiceWhoLead":"I will do a practice run for {pick}.","question":"How will you practice before your first paid job?","step":"practice","title":"Do the practice run","type":"getting-ready"}],"title":"Do the practice run"}],"title":"Do the practice run"},{"id":"l3-s3-b2","placeholder":false,"tasks":[{"id":"l3-s3-b2-t1","placeholder":false,"screens":[{"answerKey":"polish_service","eyebrow":"Test & Tweak","hint":"Straight after you've delivered your trial run, ask your customer these questions.","id":"l3-s3-b2-t1-s1","polishQuestions":[{"id":"service_explained","prompt":"Was the service explained clearly?"},{"id":"cost","prompt":"Was the cost reasonable?"},{"id":"timing","prompt":"Did the available times work for you?"},{"id":"communication","prompt":"Was communication clear and helpful?"},{"id":"delivery","prompt":"Was the service delivered well?"},{"id":"payment","prompt":"Was there a good range of payment options?"},{"id":"proof","prompt":"Did the proof of completion show the work well?"}],"polishResults":[{"id":"good","label":"was good, nothing to change"},{"id":"suggestions","label":"customer had suggestions"}],"polishSuggestion":"what was the customer's suggestion or feedback?","question":"What feedback did your trial customer give you?","step":"polish","title":"Polish your service","type":"getting-ready"}],"title":"Polish your service"}],"title":"Polish your service"}],"id":"l3-s3","placeholder":false,"title":"Test & Tweak"}]},{"floorType":"corridor","gold":{"id":"l4-gold","title":"Know where to find customers, what to say, and how to tell people about it."},"level":4,"name":"Sales","silvers":[{"bronzes":[{"id":"l4-s1-b1","placeholder":false,"tasks":[{"id":"l4-s1-b1-t1","placeholder":false,"screens":[{"answerKey":"sales_channels","c